// Generate src/rules.gen.ts from rules/registry.yaml: the RuleId union and each rule's status.
//
//   node engine/scripts/gen_rules.ts
//
// The output is committed. engine/test/rules.test.ts regenerates it in memory and fails on any difference, so a
// registry change without a regenerated file cannot land. Output is deterministic (ids sorted, LF, a final newline)
// and formatted as Biome formats it.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { parse } from "yaml";

export const REGISTRY = new URL("../../rules/registry.yaml", import.meta.url);
export const OUT = new URL("../src/rules.gen.ts", import.meta.url);

/** The same pattern as region/rules.py ID_RE and the contract's RuleId. */
const ID_RE = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*){1,3}$/;

interface RuleRow {
  id: string;
  status: string;
}

/** The rules of the registry, sorted by id. Throws on a malformed or repeated id. */
export function registryRules(text: string = readFileSync(REGISTRY, "utf8")): RuleRow[] {
  const doc = parse(text) as { rules?: { id?: unknown; status?: unknown }[] };
  const seen = new Set<string>();
  const out: RuleRow[] = [];
  for (const r of doc.rules ?? []) {
    if (typeof r.id !== "string" || !ID_RE.test(r.id)) throw new Error(`registry rule id ${String(r.id)} is malformed`);
    if (seen.has(r.id)) throw new Error(`registry rule id ${r.id} is repeated`);
    seen.add(r.id);
    out.push({ id: r.id, status: String(r.status) });
  }
  return out.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

/** The text of src/rules.gen.ts. */
export function generate(text?: string): string {
  const rules = registryRules(text);
  const lines = [
    "// Generated by engine/scripts/gen_rules.ts from rules/registry.yaml. Do not edit: run node engine/scripts/gen_rules.ts.",
    "",
    "/** Every rule id of rules/registry.yaml, sorted. */",
    "export const RULE_IDS = [",
    ...rules.map((r) => `  ${JSON.stringify(r.id)},`),
    "] as const;",
    "",
    "/** A rule id of rules/registry.yaml: the contract's RuleId pattern narrowed to the ids that exist. */",
    "export type RuleId = (typeof RULE_IDS)[number];",
    "",
    "/** Each rule's status in the registry (ratified, provisional, unratified, superseded). */",
    "export const RULE_STATUS: Readonly<Record<RuleId, string>> = {",
    ...rules.map((r) => `  ${JSON.stringify(r.id)}: ${JSON.stringify(r.status)},`),
    "};",
    "",
    "const IDS: ReadonlySet<string> = new Set(RULE_IDS);",
    "",
    "/** True when s is a rule id of the registry. */",
    "export function isRuleId(s: string): s is RuleId {",
    "  return IDS.has(s);",
    "}",
    "",
  ];
  return lines.join("\n");
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  writeFileSync(OUT, generate(), "utf8");
  console.log(`wrote ${fileURLToPath(OUT)}`);
}
